def contains(haystack, needle):
    lo, hi = 0, len(haystack) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if haystack[mid] == needle:
            return True
        if haystack[mid] < needle:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

def pair_sum(values, target):
    lo, hi = 0, len(values) - 1
    while lo < hi:
        total = values[lo] + values[hi]
        if total == target:
            return (lo, hi)
        if total < target:
            # too small, and values is sorted, so even the largest
            # remaining partner is still too small: drop lo for good
            lo += 1
        else:
            # too big, so even the smallest remaining partner is
            # still too big: drop hi for good
            hi -= 1
    return None

from collections import deque

def shortest_path(graph, start, goal):
    queue = deque([(start, [start])])
    seen = {start}
    while queue:
        node, path = queue.popleft()
        if node == goal:
            return path
        for nxt in graph.get(node, ()):
            if nxt not in seen:      # mark on enqueue, not on dequeue
                seen.add(nxt)
                queue.append((nxt, path + [nxt]))
    return None

