std::vector<int> array(n);

// 1M nodes: one allocation per node, scattered, ~32 bytes each
// plus a pointer chase per step, so ~32 MB and a cache miss on
// every dereference.
struct Node { int value; Node* next; };

// Both are O(1) amortised append. The vector copies n elements in
// total across all its growth; the list never copies anything.
// The vector still wins, because it touches memory sequentially
// and the list does not.

// Where the list wins, and it is narrow: insertion at a node you
// already hold a pointer to, with no reallocation.
//
//   LRU cache: hash map for the lookup, doubly linked list for
//   the recency order. Given the node, both `remove` and
//   `move_to_end` are O(1) -- an array would need an O(n) shift
//   or an index to maintain.
//
// The textbook table of Big O numbers hides exactly the constant
// factor that decides all of this.

class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, key):
        # No rebalancing, so the shape is whatever the keys dictate.
        node = Node(key)
        if self.root is None:
            self.root = node
            return
        cur = self.root
        while True:
            if key < cur.key:
                if cur.left is None:
                    cur.left = node
                    return
                cur = cur.left
            else:
                if cur.right is None:
                    cur.right = node
                    return
                cur = cur.right

    def height(self, node=None):
        node = self.root if node is None else node
        if node is None:
            return 0
        return 1 + max(self.height(node.left), self.height(node.right))

