  UPDATE accounts SET balance = balance - 100 WHERE id = 1;
  UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;

-- Atomic: either both legs apply or neither. A crash between the
-- two UPDATEs rolls the first one back -- money cannot be created
-- or destroyed by a process dying.
--
-- Durable: after COMMIT returns, the transfer survived, even if
-- the machine loses power one millisecond later.

-- What atomicity does NOT give you: correctness. This is atomic,
-- durable, and still wrong, because isolation lets both run at
-- once and both read the same starting balance.
BEGIN TRANSACTION ISOLATION LEVEL READ COMMITTED;  -- (in another session)
  SELECT balance FROM accounts WHERE id = 1;   -- 1000
  -- session A transfers 100 out of account 1
  UPDATE accounts SET balance = balance - 100 WHERE id = 1;
  UPDATE accounts SET balance = balance - 100 WHERE id = 1;
COMMIT;
-- Final balance is 800, not 900: the transaction is atomic and
-- durable, and it overwrote itself. Fix with a row lock or a
-- higher isolation level, which is what the I in ACID is for.

-- Setup: transfer 100 from account 1 to account 2.

-- At READ COMMITTED, the total is read twice and the two
-- reads disagree, because the second statement sees a new snapshot.
BEGIN TRANSACTION ISOLATION LEVEL READ COMMITTED;
  SELECT sum(balance) INTO total_before FROM accounts;
  -- another transaction commits a transfer here
  SELECT sum(balance) INTO total_after FROM accounts;
  -- total_before = 3000, total_after = 2900: the money moved
  -- mid-transaction, so this transaction made a decision on a
  -- number that was never true at any single instant.
COMMIT;

-- At REPEATABLE READ, both reads see the same snapshot and the
-- two totals agree. A concurrent write is not blocked; the reader
-- simply keeps seeing its own version.
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  SELECT sum(balance) INTO total_before FROM accounts;
  -- another transaction commits a transfer here
  SELECT sum(balance) INTO total_after FROM accounts;
  -- total_before = total_after = 3000
COMMIT;

-- SERIALIZABLE is the only level that makes a read-write conflict
-- an error rather than a stale-but-consistent read. Here the
-- INSERT's rows match the reader's predicate, so the reader is
-- aborted and has to retry -- which is the cost of the guarantee.
BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
  SELECT sum(balance) FROM accounts;
  UPDATE accounts SET balance = 0 WHERE id = 7;
COMMIT;   -- may raise "could not serialize access" if a
