// Two accounts, two locks. transfer(A, B) locks A then B;
// transfer(B, A) locks B then A. Run them concurrently and
// each holds what the other needs.
void transfer(Account& a, Account& b, Money amount) {
    std::scoped_lock lk{a.mutex, b.mutex};   // one thread: fine
    a.debit(amount);
    b.credit(amount);
}

// The fix: an order every caller agrees on, by resource id.
void transfer_ordered(Account& a, Account& b, Money amount) {
    Account* first  = &a;
    Account* second = &b;
    if (first->id > second->id) std::swap(first, second);

    std::scoped_lock lk{first->mutex, second->mutex};
    first->debit(amount);
    second->credit(amount);
}

