-- A procedure: a program on the server, so the row-at-a-time work
-- happens where the rows already are. Reasonable here, because
-- each step must see the previous one committed and an audit row
-- must be written atomically with the change.
CREATE PROCEDURE refund_order(order_id INT, reason TEXT)
LANGUAGE plpgsql AS $$
DECLARE prior_status TEXT;
BEGIN
  SELECT status INTO prior_status FROM orders
   WHERE id = order_id FOR UPDATE;      -- serialise concurrent refunds

  IF prior_status IS NULL THEN
    RAISE EXCEPTION 'no order %', order_id;
  END IF;
  IF prior_status <> 'settled' THEN
    RAISE EXCEPTION 'order % is %, not settled', order_id, prior_status;
  END IF;

  UPDATE orders SET status = 'refunded' WHERE id = order_id;
  INSERT INTO order_audit (order_id, action, reason)
  VALUES (order_id, 'refund', reason);
END;
$$;

